mapper.select:
select distinct x.contract_code, x.sign_company as orgId from eg_voucher x where 1 = 1 and x.scene_code = 'SSF' and x.business_code ='ZLYW' and x.system_code in ('MFXT','FINHUB') and x.del_flag = '0'
and x.org_id = #{queryDTO.orgId}
and x.contract_code = #{queryDTO.contractCode}
and to_char(x.voucher_date,'YYYY-MM-DD') >= to_char(to_date(#{queryDTO.startAccountDate},'YYYY-MM-DD'),'YYYY-MM-DD')
and to_char(x.voucher_date,'YYYY-MM-DD') <= to_char(to_date(#{queryDTO.endAccountDate},'YYYY-MM-DD'),'YYYY-MM-DD')

select x.id as voucherId, x.contract_code, x.contract_name, x.sign_company as orgId, x.voucher_date as accountDate, x.order_id, x.batch_type, x.voucher_summary from eg_voucher x where 1 = 1 and x.scene_code = 'SSF' and x.business_code ='ZLYW' and x.system_code in ('MFXT','FINHUB') and x.del_flag = '0'
and x.org_id = #{queryDTO.orgId}
and x.contract_code = #{queryDTO.contractCode}

select eve.*, x.order_id from eg_voucher_entry eve inner join eg_voucher x on eve.voucher_id = x.id where 1 = 1 and x.del_flag = '0' and eve.del_flag = '0' and x.scene_code = 'SSF' and x.business_code = 'ZLYW' and x.system_code in ('MFXT','FINHUB')
and x.contract_code = #{condition.contractCode}
and x.org_id = #{condition.orgId}
